class Solution { fun diagonalSort(mat:Array<IntArray>):Array<IntArray>{val groups=mutableMapOf<Int,MutableList<Int>>();for(r in mat.indices)for(c in mat[0].indices)groups.getOrPut(r-c){mutableListOf()}.add(mat[r][c]);for(values in groups.values)values.sort();val index=mutableMapOf<Int,Int>();for(r in mat.indices)for(c in mat[0].indices){val key=r-c;val position=index[key]?:0;mat[r][c]=groups[key]!![position];index[key]=position+1};return mat} }
